import static org.hamcrest.Matchers.nullValue;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberLoanHistoryIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void history_includes_returned_loans_newest_loan_first_with_late_fee() throws Exception {
        String memberId = registerMember("강하윤");
        String lateLoanId = loanBook(registerBook("History Late Book"), memberId, LocalDate.of(2026, 1, 1));
        String onTimeLoanId = loanBook(registerBook("History On Time Book"), memberId, LocalDate.of(2026, 1, 10));
        String activeLoanId = loanBook(registerBook("History Active Book"), memberId, LocalDate.of(2026, 2, 2));

        // 기한 2026-01-15 를 5일 넘겨 반납: 500원
        returnBook(lateLoanId, "2026-01-20");
        // 기한 2026-01-24 이전에 반납: 연체 없음
        returnBook(onTimeLoanId, "2026-01-12");

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(3))
                .andExpect(jsonPath("$[0].loanId").value(activeLoanId))
                .andExpect(jsonPath("$[0].title").value("History Active Book"))
