import com.example.lending.domain.AuditAction;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Index;
import jakarta.persistence.Table;

import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "audit_log", indexes = @Index(name = "idx_audit_log_target", columnList = "targetId"))
public class AuditLogJpaEntity {

    // 같은 시각에 남은 기록의 순서를 정하려고 id 를 DB 가 증가시킨다
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private AuditAction action;

    @Column(nullable = false)
    private UUID targetId;

    // 회원과 무관한 작업(폐기)은 null
    private UUID memberId;

    @Column(nullable = false)
    private Instant occurredAt;

    protected AuditLogJpaEntity() {
    }

    public AuditLogJpaEntity(AuditAction action, UUID targetId, UUID memberId, Instant occurredAt) {
        this.action = action;
        this.targetId = targetId;
        this.memberId = memberId;
        this.occurredAt = occurredAt;
    }

    public Long getId() {
        return id;
    }

    public AuditAction getAction() {
        return action;
    }

    public UUID getTargetId() {
        return targetId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public Instant getOccurredAt() {
        return occurredAt;
    }
}
