package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMonthlyStatsUseCase;
import com.example.lending.application.port.out.LoadLoanStatsPort;
import com.example.lending.domain.Loan;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

@Service
@Transactional(readOnly = true)
public class GetMonthlyStatsService implements GetMonthlyStatsUseCase {

    private final LoadLoanStatsPort loadLoanStatsPort;

    public GetMonthlyStatsService(LoadLoanStatsPort loadLoanStatsPort) {
        this.loadLoanStatsPort = loadLoanStatsPort;
    }

    @Override
    public MonthlyStats getMonthlyStats(int year, int month) {
        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("month must be between 1 and 12");
        }
        YearMonth yearMonth = YearMonth.of(year, month);
        LocalDate from = yearMonth.atDay(1);
        LocalDate to = yearMonth.plusMonths(1).atDay(1);

        long loanCount = loadLoanStatsPort.countLoansLoanedBetween(from, to);
        List<Loan> returned = loadLoanStatsPort.loadLoansReturnedBetween(from, to);
        // 연체료가 0보다 큰 반납을 연체 발생으로 본다
        long overdueCount = returned.stream().filter(loan -> loan.getLateFee() > 0).count();
        long lateFeeTotal = returned.stream().mapToLong(Loan::getLateFee).sum();
        return new MonthlyStats(year, month, loanCount, returned.size(), overdueCount, lateFeeTotal);
    }
}
