package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MonthlyStatsIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    // 다른 테스트가 쓰지 않는 2026-05 로 검증해서 공유 DB 의 다른 데이터와 섞이지 않게 한다
    @Test
    void counts_loans_by_loan_date_and_returns_and_late_fees_by_return_date() throws Exception {
        String memberId = registerMember("통계하윤");
        String aprilLoanId = loanBook(registerBook("Stats April Loan Book"), memberId, LocalDate.of(2026, 4, 20));
        String lateInMayId = loanBook(registerBook("Stats Late In May Book"), memberId, LocalDate.of(2026, 5, 1));
        String activeId = loanBook(registerBook("Stats Active Book"), memberId, LocalDate.of(2026, 5, 2));
        String returnedNextMonthId = loanBook(registerBook("Stats Returned Next Month Book"), memberId,
                LocalDate.of(2026, 5, 3));
        String lateReturnedInMayId = loanBook(registerBook("Stats Late Returned In May Book"), memberId,
                LocalDate.of(2026, 5, 4));

        // aprilLoan: 기한 2026-05-04, 반납 05-10 → 6일 연체 600원 (반납은 5월)
        returnBook(aprilLoanId, "2026-05-10");
        // lateInMay: 기한 2026-05-15, 반납 05-05 → 연체 없음 (반납은 5월)
        returnBook(lateInMayId, "2026-05-05");
        // returnedNextMonth: 기한 2026-05-17, 반납 06-02 → 6월 반납이라 5월 통계에서 제외
        returnBook(returnedNextMonthId, "2026-06-02");
        // lateReturnedInMay: 기한 2026-05-18, 반납 05-31 → 13일 연체 1300원 (반납은 5월)
        returnBook(lateReturnedInMayId, "2026-05-31");

        // 대출일 5월: lateInMay, active, returnedNextMonth, lateReturnedInMay = 4건
        // 반납일 5월: aprilLoan, lateInMay, lateReturnedInMay = 3건, 연체 2건, 연체료 1900원
        mockMvc.perform(get("/stats/monthly").param("year", "2026").param("month", "5"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(2026))
                .andExpect(jsonPath("$.month").value(5))
                .andExpect(jsonPath("$.loanCount").value(4))
                .andExpect(jsonPath("$.returnCount").value(3))
                .andExpect(jsonPath("$.overdueCount").value(2))
                .andExpect(jsonPath("$.lateFeeTotal").value(1900));
    }

    @Test
    void month_without_activity_returns_zeros() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2026").param("month", "7"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanCount").value(0))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
    }

    @Test
    void month_out_of_range_returns_400() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2026").param("month", "13"))
                .andExpect(status().isBadRequest());
    }

    private void returnBook(String loanId, String returnedAt) throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + returnedAt + "\"}"))
                .andExpect(status().isOk());
    }

    private String loanBook(String bookId, String memberId, LocalDate loanedAt) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(bookId, memberId, loanedAt))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    record LoanBody(String bookId, String memberId, LocalDate loanedAt) {
    }
}
